import os


def claim(root, agent):
    """Claim one open task for `agent` and return its name, or None. Two agents must never get the same task.
    The board: root/open/<task>, root/claimed/<task>.<agent>, and root/.claims/ for claim tokens."""
    for name in sorted(p.name for p in (root / "open").iterdir()):
        token = root / ".claims" / name                # keyed on the task, so claimers contend for one name
        try:
            fd = os.open(token, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            continue                                   # another agent holds this task
        os.close(fd)
        try:
            os.rename(root / "open" / name, root / "claimed" / f"{name}.{agent}")
        except OSError:
            token.unlink(missing_ok=True)              # nobody else holds the token: release it
            continue
        return name
    return None
